#!/usr/bin/env python3
import json
import subprocess
import os
import sys

def is_app_running(app_name):
    """Check if an application is currently running."""
    try:
        cmd = ['pgrep', '-f', f'{app_name}']
        result = subprocess.run(cmd, capture_output=True, text=True)
        return result.returncode == 0
    except:
        return False

def create_management_menu(app_name, app_path):
    """Create management menu for the selected app."""
    items = []
    running = is_app_running(app_name)

    if running:
        # Quick Restart (top option for running apps)
        items.append({
            "title": f"🔄 Quick Restart {app_name}",
            "subtitle": "Terminate and relaunch the application",
            "arg": f"quick_restart|{app_name}|{app_path}",
            "icon": {"type": "fileicon", "path": app_path}
        })

        # Force Quit
        items.append({
            "title": f"❌ Force Quit {app_name}",
            "subtitle": "Forcefully terminate the application",
            "arg": f"force_quit|{app_name}|{app_path}",
            "icon": {"type": "fileicon", "path": app_path}
        })

        # Graceful Quit
        items.append({
            "title": f"🛑 Quit {app_name}",
            "subtitle": "Gracefully quit the application",
            "arg": f"quit|{app_name}|{app_path}",
            "icon": {"type": "fileicon", "path": app_path}
        })
    else:
        # Launch (for non-running apps)
        items.append({
            "title": f"🚀 Launch {app_name}",
            "subtitle": "Start the application",
            "arg": f"launch|{app_name}|{app_path}",
            "icon": {"type": "fileicon", "path": app_path}
        })

    # Always available options
    items.extend([
        {
            "title": f"📁 Show {app_name} in Finder",
            "subtitle": "Reveal application in Finder",
            "arg": f"show_in_finder|{app_path}",
            "icon": {"type": "fileicon", "path": app_path}
        },
        {
            "title": f"ℹ️ Get Info for {app_name}",
            "subtitle": "Show application information",
            "arg": f"get_info|{app_path}",
            "icon": {"type": "fileicon", "path": app_path}
        }
    ])

    return {"items": items}

def main():
    try:
        query = sys.argv[1] if len(sys.argv) > 1 else ""

        if query.startswith("manage|"):
            # Parse the management command
            parts = query.split("|", 2)
            if len(parts) >= 3:
                _, app_name, app_path = parts
                result = create_management_menu(app_name, app_path)
            else:
                result = {"items": [{"title": "Invalid app selection", "valid": False}]}
        else:
            result = {"items": [{"title": "No app selected", "valid": False}]}

        print(json.dumps(result))

    except Exception as e:
        print(json.dumps({
            "items": [{
                "title": "Error creating menu",
                "subtitle": f"Error: {str(e)}",
                "valid": False
            }]
        }))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import subprocess
import os
import sys

def get_running_apps():
    """Get list of running applications with their info."""
    try:
        query = sys.argv[1].lower() if len(sys.argv) > 1 and sys.argv[1] else ""

        # Use osascript to get running applications - more reliable
        applescript = '''
        tell application "System Events"
            set appList to {}
            repeat with proc in (every application process whose visible is true)
                set appName to name of proc
                set appList to appList & appName
            end repeat
        end tell
        return appList
        '''

        result = subprocess.run(['osascript', '-e', applescript], 
                              capture_output=True, text=True, check=True)

        running_app_names = []
        if result.stdout.strip():
            # Parse the AppleScript list output
            output = result.stdout.strip()
            if output:
                # Remove the outer brackets and split by comma
                apps_str = output.strip()
                if apps_str:
                    running_app_names = [app.strip() for app in apps_str.split(', ')]

        # Get all installed applications
        app_dirs = ['/Applications', '/System/Applications', os.path.expanduser('~/Applications')]
        all_apps = {}

        for app_dir in app_dirs:
            if os.path.exists(app_dir):
                try:
                    for item in os.listdir(app_dir):
                        if item.endswith('.app'):
                            app_name = item[:-4]  # Remove .app extension
                            app_path = os.path.join(app_dir, item)
                            if app_name not in all_apps:  # Prefer /Applications over others
                                all_apps[app_name] = app_path
                except PermissionError:
                    continue

        items = []

        # First add all running applications
        for app_name in sorted(set(running_app_names)):
            if not query or query in app_name.lower():
                app_path = all_apps.get(app_name, f"/Applications/{app_name}.app")
                items.append({
                    "title": f"🟢 {app_name}",
                    "subtitle": "Running - Click to manage this application",
                    "arg": f"manage|{app_name}|{app_path}",
                    "icon": {"type": "fileicon", "path": app_path}
                })

        # Then add matching non-running apps if there's a search query
        if query:
            for app_name, app_path in all_apps.items():
                if (query in app_name.lower() and 
                    app_name not in running_app_names):
                    items.append({
                        "title": f"⚪ {app_name}",
                        "subtitle": "Not running - Click to manage this application", 
                        "arg": f"manage|{app_name}|{app_path}",
                        "icon": {"type": "fileicon", "path": app_path}
                    })

        # If no query and no running apps, show some common apps
        if not items and not query:
            common_apps = ['Safari', 'Chrome', 'Firefox', 'Finder', 'Terminal', 'TextEdit']
            for app_name in common_apps:
                app_path = all_apps.get(app_name, f"/Applications/{app_name}.app")
                if os.path.exists(app_path):
                    items.append({
                        "title": f"⚪ {app_name}",
                        "subtitle": "Not running - Click to manage this application",
                        "arg": f"manage|{app_name}|{app_path}",
                        "icon": {"type": "fileicon", "path": app_path}
                    })

        if not items:
            items.append({
                "title": "No applications found",
                "subtitle": "Try typing to search for applications",
                "arg": "none",
                "valid": False
            })

        return {"items": items}

    except Exception as e:
        # Debug output
        return {
            "items": [{
                "title": "Debug - Error loading applications",
                "subtitle": f"Error: {str(e)} | Args: {sys.argv}",
                "arg": "error",
                "valid": False
            }]
        }

if __name__ == "__main__":
    result = get_running_apps()
    print(json.dumps(result))
